"""Explicit study-to-draft transition and mutually exclusive purchase views."""
CSS='''
body[data-purchase-mode=draft] #po-saved-ribbons{display:none!important}body[data-purchase-mode=saved] #po-draft-ribbons,body[data-purchase-mode=saved] #save{display:none!important}
body[data-purchase-mode=saved] #po-draft-negotiation,body[data-purchase-mode=saved] #po-conditions>.po-negotiation-scroll,body[data-purchase-mode=saved] #po-conditions>.po-shared-conditions,body[data-purchase-mode=saved] #po-stock-assumptions,body[data-purchase-mode=saved] #po-cash,body[data-purchase-mode=saved] #po-conditions>.po-condition-note,body[data-purchase-mode=saved] #po-conditions>#po-cash-alert,body[data-purchase-mode=saved] #po-conditions>#comparison{display:none!important}
#po-draft-origin{padding:12px 14px;background:#eaf2ff;border:1px solid #bdd0eb;border-radius:7px;font-size:14px;line-height:1.5;margin:12px 0}#po-create-study-draft{background:#1756b2;color:white;border:1px solid #1756b2}#po-draft-copy-notice{font-size:13px;line-height:1.5}
'''
JS=r'''
let purchaseDraftSource=()=>null;
(function(){
 const form=$('form'),heading=$('po-conditions').querySelector('.po-heading'),title=heading.querySelector('h2'),help=heading.querySelector('p'),originalTitle=title.textContent,originalHelp=help.textContent;
 const banner=document.createElement('p');banner.id='po-draft-origin';banner.hidden=true;heading.after(banner);let study=null,source=null,sourceIdentity=null,epoch=0,hydrating=null,reviewOwner=null;
 function mode(value){document.body.dataset.purchaseMode=value;if(value==='draft'){title.textContent=originalTitle;help.textContent=originalHelp;$('review-panel').hidden=true;$('po-cash-saved')?.setAttribute('hidden','')}else{title.textContent='CONSULTAR ESTUDIO GUARDADO';help.textContent='Consulta sus resultados o crea un borrador nuevo para cambiar las condiciones.';banner.hidden=true;const ribbon=$('po-saved-ribbons');if(ribbon)$('po-draft-ribbons').before(ribbon)}}
 function clearOrigin(){source=null;sourceIdentity=null;banner.hidden=true;banner.textContent=''}
 purchaseDraftSource=()=>source?structuredClone(source):null;
 function identity(){return [$('dataset').value,$('supplier').value,$('article').value].join('|')}
 function edit(event){if(hydrating!==null&&!event.isTrusted)return;epoch++;if(sourceIdentity&&identity()!==sourceIdentity)clearOrigin()}
 form.addEventListener('submit',event=>{if(document.body.dataset.purchaseMode==='saved'){event.preventDefault();event.stopImmediatePropagation();$('notice').textContent='Estás consultando un estudio. Crea un borrador para guardar una propuesta nueva.'}},true);
 form.addEventListener('input',edit,true);form.addEventListener('change',edit,true);form.addEventListener('reset',clearOrigin);$('dataset').addEventListener('change',()=>{epoch++;study=null;clearOrigin();mode('draft')});
 const clear=clearPurchaseSummary;clearPurchaseSummary=function(){mode('draft');clear();if(source){banner.hidden=false;banner.textContent='Borrador desde '+source.reference+' · Sin guardar. El estudio original permanece intacto.'}};
 const renderSaved=renderPurchaseCashSaved;renderPurchaseCashSaved=function(proposal){renderSaved(proposal);const box=$('po-cash-saved');if(box)for(const duplicate of box.querySelectorAll('.po-purchase-summary,.po-alternatives-table'))duplicate.remove()};
 const finance=renderFinancialContext;renderFinancialContext=function(report){finance(report);study=report;epoch++;mode('saved');const create=document.createElement('button');create.type='button';create.id='po-create-study-draft';create.textContent='Crear borrador desde este estudio';const notice=document.createElement('p');notice.id='po-draft-copy-notice';notice.setAttribute('role','status');notice.textContent='Copia condiciones, cuotas y supuestos. Sustituye el formulario de trabajo; no modifica este estudio.';const back=$('po-return-draft');back.textContent='Volver a mi formulario';back.before(create);back.after(notice);create.onclick=()=>copyStudy(create,notice);};
 window.purchaseReviewIsCurrent=(id,dataset)=>!!reviewOwner&&reviewOwner.id===id&&reviewOwner.dataset===dataset&&reviewOwner.epoch===epoch;
 const review=reviewSaved;reviewSaved=async function(id,button){const owner={id,dataset:$('dataset').value,epoch:++epoch};reviewOwner=owner;purchaseCashSequence++;clearTimeout(purchaseCashTimer);purchaseCashController?.abort();clearPurchaseSummary();clearPurchaseAlternativesTable();const result=await review(id,button);if(reviewOwner===owner&&owner.epoch!==epoch&&document.body.dataset.purchaseMode==='draft'&&$('dataset').value===owner.dataset)$('notice').textContent='Revisión anterior descartada: has cambiado el formulario. Tus datos de edición se conservan.';if(study?.proposal_id===id&&document.body.dataset.purchaseMode==='saved'){if(window.purchaseGuideNavigate)purchaseGuideNavigate('po-save');else document.querySelector('.po-nav a[href="#po-conditions"]').click();$('po-study-state').scrollIntoView({block:'start'})}return result};
 async function copyStudy(button,notice){const selected=study;if(!selected)return;const dataset=$('dataset').value,request=++epoch;const ownsContext=()=>request===epoch&&dataset===$('dataset').value&&study===selected;button.disabled=true;notice.textContent='Preparando la copia…';try{const draft=await api('/api/purchases/draft',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({dataset_id:dataset,proposal_id:selected.proposal_id,documentary_context_fingerprint:state.documentary_context.fingerprint})});if(!ownsContext()){notice.textContent='La selección o el formulario han cambiado. No se ha aplicado la copia.';return}
 hydrating=request;purchaseCashSequence++;clearTimeout(purchaseCashTimer);purchaseCashController?.abort();clearPurchaseSummary();clearPurchaseAlternativesTable();form.reset();await Promise.resolve();if(!ownsContext())return;const values=draft.values;$('supplier').value=values.supplier_id;articles(values.article_id);await new Promise(requestAnimationFrame);if(!ownsContext())return;
 for(const key of ['quantity','order_date','reference','delivery_location']){const input=form.elements[key];if(input)input.value=key==='order_date'?stockDate(values[key]):values[key]??''}
 $('payment-plan-rows').replaceChildren();$('payment-plan-enabled').checked=!!values.payment_installments;for(const item of values.payment_installments||[]){addPaymentRow();const row=$('payment-plan-rows').lastElementChild;for(const key of ['component','amount','due_date'])row.querySelector('[data-payment-field='+key+']').value=key==='due_date'?stockDate(item[key]):item[key]}paymentRowsEnabled();
 loadPurchaseNegotiationDraft(values.negotiation_alternatives);await new Promise(requestAnimationFrame);if(!ownsContext())return;loadPurchaseStockDraft(values.stock_planning||null);source=values.draft_source;sourceIdentity=identity();banner.hidden=false;banner.textContent='Borrador desde '+source.reference+' · Sin guardar. '+(values.stock_planning?'Revisa y confirma los supuestos de stock copiados.':'El estudio original permanece intacto.');$('notice').textContent=draft.message;if(hydrating===request)hydrating=null;form.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('.po-nav a[href="#po-conditions"]').click();schedulePurchaseCash();banner.scrollIntoView({block:'center'});
 }catch(error){notice.textContent=error.message;if(hydrating===request&&ownsContext()){clearOrigin();mode('draft');$('notice').textContent='No se ha completado la copia: '+error.message+' No se ha guardado ninguna propuesta.'}}finally{if(hydrating===request)hydrating=null;button.disabled=false}}
 mode('draft');
})();
'''
